package com.trampolim.api.communication;

import java.time.*;
import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.trampolim.api.catalog.CatalogItem;
import com.trampolim.api.catalog.OpportunityAlertService;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

/** One instance per database. No external transport, shared identity or cross-trail SQL. */
public class CommunicationStore {
 public final String trail;
 private final String accounts;private final JdbcTemplate db;private final TransactionTemplate tx;
 private final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 public record Preferences(boolean enabled,int dailyLimit,int minimumIntervalMinutes,Map<String,Boolean> categories,Long expectedRevision){}
 public CommunicationStore(JdbcTemplate db,PlatformTransactionManager manager,String trail){this.db=db;this.tx=new TransactionTemplate(manager);this.trail=trail;accounts=switch(trail){case "OPORTUNIDADES"->"app_users";case "EMPRESAS"->"company_users";case "CAPACITA"->"student_users";default->throw new IllegalArgumentException();};}
 public record QueueSnapshot(long pending,long failed,double oldestDueSeconds){}
 public QueueSnapshot queueSnapshot(){
  return db.queryForObject("SELECT COUNT(*) FILTER (WHERE status='PENDING') AS pending, COUNT(*) FILTER (WHERE status='FAILED') AS failed, COALESCE(EXTRACT(EPOCH FROM CURRENT_TIMESTAMP-MIN(next_attempt_at) FILTER (WHERE status='PENDING' AND next_attempt_at<=CURRENT_TIMESTAMP)),0) AS oldest FROM communication_deliveries",(r,n)->new QueueSnapshot(r.getLong("pending"),r.getLong("failed"),Math.max(0,r.getDouble("oldest"))));
 }
 private Set<String> kinds(){return CommunicationTemplates.kinds(trail);}
 private String active(){return "email_verified=TRUE"+(trail.equals("OPORTUNIDADES")?" AND account_type='PERSON'":" AND account_status='ACTIVE'");}
 public long user(String email){if(email==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return db.queryForList("SELECT id FROM "+accounts+" WHERE LOWER(email)=LOWER(?) AND "+active(),email).stream().map(row->num(row,"id")).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Use uma conta verificada e ativa da trilha correspondente."));}
 private void serial(long user){db.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"communications:"+trail+":"+user);}
 private Map<String,Object> settings(long user){var rows=db.queryForList("SELECT enabled,daily_limit,minimum_interval_minutes,categories,revision FROM communication_settings WHERE user_id=?",user);if(rows.isEmpty())return Map.of("enabled",true,"daily_limit",100,"minimum_interval_minutes",0,"categories",Map.of(),"revision",0L);return rows.getFirst();}
 private Map<String,Boolean> categories(Object raw){try{if(raw instanceof Map<?,?> map){var result=new HashMap<String,Boolean>();map.forEach((k,v)->{if(v instanceof Boolean b)result.put(k.toString(),b);});return result;}return json.readValue(raw.toString(),json.getTypeFactory().constructMapType(HashMap.class,String.class,Boolean.class));}catch(Exception error){throw new IllegalStateException("Invalid communication settings");}}
 public boolean allowed(long user,String kind){var value=settings(user);return Boolean.TRUE.equals(value.get("enabled"))&&!Boolean.FALSE.equals(categories(value.get("categories")).get(kind));}
 public Map<String,Object> preferences(String email){long id=user(email);var s=settings(id);return Map.of("enabled",s.get("enabled"),"dailyLimit",s.get("daily_limit"),"minimumIntervalMinutes",s.get("minimum_interval_minutes"),"categories",categories(s.get("categories")),"revision",s.get("revision"),"availableKinds",kinds(),"channels",Map.of("IN_APP","AVAILABLE","EMAIL","NOT_ACTIVATED","WHATSAPP_BUSINESS","NOT_ACTIVATED"));}
 public Map<String,Object> save(String email,Preferences input){long id=user(email);if(input==null||input.expectedRevision()==null||input.expectedRevision()<0||input.dailyLimit()<1||input.dailyLimit()>500||input.minimumIntervalMinutes()<0||input.minimumIntervalMinutes()>10080||input.categories()==null||!kinds().containsAll(input.categories().keySet())||input.categories().values().stream().anyMatch(Objects::isNull))bad();tx.executeWithoutResult(status->{serial(id);var s=settings(id);if(num(s,"revision")!=input.expectedRevision())throw new ResponseStatusException(HttpStatus.CONFLICT,"As preferências mudaram. Consulte a versão atual.");String data;try{data=json.writeValueAsString(new TreeMap<>(input.categories()));}catch(Exception e){throw new IllegalStateException(e);}long revision=input.expectedRevision()+1;db.update("INSERT INTO communication_settings(user_id,enabled,daily_limit,minimum_interval_minutes,categories,revision) VALUES (?,?,?,?,?::jsonb,?) ON CONFLICT(user_id) DO UPDATE SET enabled=EXCLUDED.enabled,daily_limit=EXCLUDED.daily_limit,minimum_interval_minutes=EXCLUDED.minimum_interval_minutes,categories=EXCLUDED.categories,revision=EXCLUDED.revision,updated_at=CURRENT_TIMESTAMP",id,input.enabled(),input.dailyLimit(),input.minimumIntervalMinutes(),data,revision);db.update("INSERT INTO communication_preference_audit(user_id,revision,settings) VALUES (?,?,jsonb_build_object('enabled',?::boolean,'dailyLimit',?::int,'minimumIntervalMinutes',?::int,'categories',?::jsonb))",id,revision,input.enabled(),input.dailyLimit(),input.minimumIntervalMinutes(),data);if(!input.enabled())db.update("UPDATE communication_deliveries SET status='SUPPRESSED',reason='PREFERENCE_DISABLED' WHERE user_id=? AND status='PENDING'",id);else for(var category:input.categories().entrySet())if(!category.getValue())db.update("UPDATE communication_deliveries SET status='SUPPRESSED',reason='PREFERENCE_DISABLED' WHERE user_id=? AND kind=? AND status='PENDING'",id,category.getKey());});return preferences(email);}
 public Map<String,Object> history(String email,long before,int limit,boolean deliveryStatus){long id=user(email);if(before<1||limit<1||limit>50)bad();String fields=deliveryStatus?"id,kind,status,reason,attempts,created_at,delivered_at,read_at,next_attempt_at":"id,kind,title,body,target,template_version,resource_id,legacy_id,created_at,delivered_at,read_at";var rows=db.queryForList("SELECT "+fields+" FROM communication_deliveries WHERE user_id=? AND id<?"+(deliveryStatus?"":" AND status='DELIVERED'")+" ORDER BY id DESC LIMIT ?",id,before,limit+1);boolean more=rows.size()>limit;var items=rows.stream().limit(limit).toList();var result=new LinkedHashMap<String,Object>();result.put("channel","IN_APP");result.put("deliveryMeaning","PERSISTED_INBOX_NOT_EXTERNAL_RECEIPT");result.put("items",items);result.put("nextCursor",more?num(items.getLast(),"id"):null);result.put("unreadCount",db.queryForObject("SELECT count(*) FROM communication_deliveries WHERE user_id=? AND status='DELIVERED' AND read_at IS NULL",Long.class,id));return result;}
 public void read(String email,long id){long uid=user(email);tx.executeWithoutResult(status->{serial(uid);var rows=db.queryForList("UPDATE communication_deliveries SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=? AND user_id=? AND status='DELIVERED' RETURNING legacy_id",id,uid);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(trail.equals("CAPACITA")&&rows.getFirst().get("legacy_id")!=null)db.update("UPDATE learning_notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=? AND user_id=?",rows.getFirst().get("legacy_id"),uid);});}
 public void readLegacy(String email,long id){if(!trail.equals("CAPACITA"))throw new IllegalArgumentException();long uid=user(email);tx.executeWithoutResult(status->{serial(uid);if(db.update("UPDATE learning_notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=? AND user_id=?",id,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);db.update("UPDATE communication_deliveries SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE legacy_id=? AND user_id=? AND status='DELIVERED'",id,uid);});}
 private long enqueue(long user,String key,String kind,long resource,long scope,String legacyKind,Long message){if(!kinds().contains(kind)||key==null||key.length()>160||resource<1||scope<1)throw new IllegalArgumentException("Invalid local notification event");var rows=db.queryForList("INSERT INTO communication_deliveries(user_id,event_key,kind,resource_id,scope_id,legacy_kind,legacy_message_id) SELECT id,?,?,?,?,?,? FROM "+accounts+" WHERE id=? AND "+active()+" ON CONFLICT(user_id,event_key) DO NOTHING RETURNING id",key,kind,resource,scope,legacyKind,message,user);return rows.isEmpty()?0:num(rows.getFirst(),"id");}
 public void question(long receiver,long thread,Long message,String legacyKind){if(!trail.equals("CAPACITA")||!Set.of("QUESTION","FOLLOW_UP","REPLY","STATUS").contains(legacyKind))throw new IllegalArgumentException();tx.executeWithoutResult(status->{serial(receiver);String version=message==null?Objects.toString(db.queryForObject("SELECT updated_at FROM learning_questions WHERE id=?",Object.class,thread)):message.toString();long id=enqueue(receiver,"question:"+thread+":"+legacyKind+":"+version,legacyKind.equals("REPLY")?"QUESTION_REPLY":"QUESTION_ACTIVITY",thread,thread,legacyKind,message);if(id>0)deliverLocked(id,receiver);});}
 public void pumpSources(){var candidates=db.queryForList("SELECT id FROM communication_events WHERE state='PENDING' AND next_attempt_at<=CURRENT_TIMESTAMP ORDER BY id LIMIT 10");for(var item:candidates){long id=num(item,"id");try{tx.executeWithoutResult(status->{var rows=db.queryForList("SELECT * FROM communication_events WHERE id=? AND state='PENDING' AND next_attempt_at<=CURRENT_TIMESTAMP FOR UPDATE SKIP LOCKED",id);if(rows.isEmpty())return;var e=rows.getFirst();if(((java.sql.Timestamp)e.get("created_at")).toInstant().isBefore(Instant.now().minus(Duration.ofDays(30)))){db.update("UPDATE communication_events SET state='COMPLETED',reason='EXPIRED' WHERE id=?",id);return;}var recipients=recipients(e);for(var recipient:recipients){long uid=num(recipient,"id");if(!e.get("kind").equals("NEW_MATCH")||matches(uid,num(e,"resource_id")))enqueue(uid,e.get("source_key").toString(),e.get("kind").toString(),num(e,"resource_id"),num(e,"scope_id"),null,null);}if(recipients.size()<100)db.update("UPDATE communication_events SET state='COMPLETED' WHERE id=?",id);else db.update("UPDATE communication_events SET recipient_cursor=? WHERE id=?",num(recipients.getLast(),"id"),id);});}catch(RuntimeException error){db.update("UPDATE communication_events SET attempts=attempts+1,state=CASE WHEN attempts+1>=5 THEN 'FAILED' ELSE 'PENDING' END,reason='PERSISTENCE_ERROR',next_attempt_at=CURRENT_TIMESTAMP+make_interval(secs=>LEAST(900,10*power(2,LEAST(attempts,6)))::int) WHERE id=? AND state='PENDING'",id);}}}
 private List<Map<String,Object>> recipients(Map<String,Object> e){long cursor=num(e,"recipient_cursor"),scope=num(e,"scope_id");String kind=e.get("kind").toString();
  if(trail.equals("OPORTUNIDADES")){if(kind.equals("APPLICATION_UPDATED"))return db.queryForList("SELECT id FROM app_users WHERE id=? AND id>? AND "+active(),scope,cursor);if(kind.equals("NEW_MATCH"))return db.queryForList("SELECT id FROM app_users WHERE id>? AND created_at<=? AND alert_preferences IS NOT NULL AND "+active()+" ORDER BY id LIMIT 100",cursor,e.get("created_at"));}
  if(trail.equals("EMPRESAS")&&kind.equals("TRUST_REVIEW"))return db.queryForList("SELECT u.id FROM company_users u JOIN companies c ON c.id=? WHERE u.id>? AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND (c.owner_user_id=u.id OR EXISTS(SELECT 1 FROM company_members m WHERE m.company_id=c.id AND m.user_id=u.id AND m.role IN ('OWNER','ADMIN','RECRUITER'))) ORDER BY u.id LIMIT 100",scope,cursor);
  if(trail.equals("EMPRESAS")&&Set.of("APPLICATION_UPDATED","INTERVIEW_INVITATION").contains(kind))return db.queryForList("SELECT u.id FROM company_users u JOIN companies c ON c.id=? WHERE u.id>? AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND c.verification_status<>'SUSPENDED' AND (c.owner_user_id=u.id OR EXISTS(SELECT 1 FROM company_members m WHERE m.company_id=c.id AND m.user_id=u.id AND m.role IN ('OWNER','RECRUITER'))) ORDER BY u.id LIMIT 100",scope,cursor);
  if(trail.equals("CAPACITA")&&Set.of("COURSE_CHANGED","ASSESSMENT_AVAILABLE").contains(kind))return db.queryForList("SELECT u.id FROM student_users u WHERE u.id>? AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND EXISTS(SELECT 1 FROM learning_lesson_progress p JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id WHERE p.student_id=u.id AND s.course_id=?) ORDER BY u.id LIMIT 100",cursor,scope);
  throw new IllegalStateException("Unsupported trail event");
 }
 private boolean matches(long uid,long itemId){var users=db.queryForList("SELECT alert_preferences FROM app_users WHERE id=?",uid);var items=db.queryForList("SELECT * FROM catalog_items WHERE id=? AND kind='job' AND active=TRUE AND moderation_status='APPROVED' AND (expires_at IS NULL OR expires_at>=CURRENT_DATE)",itemId);if(users.isEmpty()||items.isEmpty()||users.getFirst().get("alert_preferences")==null)return false;try{var prefs=json.readTree(users.getFirst().get("alert_preferences").toString());if(!prefs.path("enabled").asBoolean(false))return false;var row=items.getFirst();var item=new CatalogItem();item.setTitle((String)row.get("title"));item.setDescription((String)row.get("description"));item.setProvider((String)row.get("provider"));item.setArea((String)row.get("area"));item.setLocation((String)row.get("location"));item.setModality((String)row.get("modality"));item.setContractType((String)row.get("contract_type"));item.setWorkSchedule((String)row.get("work_schedule"));item.setLatitude(row.get("latitude") instanceof Number n?n.doubleValue():null);item.setLongitude(row.get("longitude") instanceof Number n?n.doubleValue():null);return OpportunityAlertService.matches(prefs,item);}catch(com.fasterxml.jackson.core.JsonProcessingException malformed){return false;}}
 public void pumpDeliveries(){for(var item:db.queryForList("SELECT id,user_id FROM communication_deliveries WHERE status='PENDING' AND next_attempt_at<=CURRENT_TIMESTAMP ORDER BY id LIMIT 100")){long id=num(item,"id"),uid=num(item,"user_id");try{tx.executeWithoutResult(status->{serial(uid);deliverLocked(id,uid);});}catch(RuntimeException error){tx.executeWithoutResult(status->{serial(uid);db.update("UPDATE communication_deliveries SET attempts=attempts+1,status=CASE WHEN attempts+1>=5 THEN 'FAILED' ELSE 'PENDING' END,reason='PERSISTENCE_ERROR',next_attempt_at=CURRENT_TIMESTAMP+make_interval(secs=>LEAST(900,10*power(2,LEAST(attempts,6)))::int) WHERE id=? AND user_id=? AND status='PENDING'",id,uid);});}}}
 private void suppress(long id,String reason){db.update("UPDATE communication_deliveries SET status='SUPPRESSED',reason=? WHERE id=?",reason,id);}
 private void deliverLocked(long id,long uid){var rows=db.queryForList("SELECT * FROM communication_deliveries WHERE id=? AND user_id=? AND status='PENDING' AND next_attempt_at<=CURRENT_TIMESTAMP FOR UPDATE SKIP LOCKED",id,uid);if(rows.isEmpty())return;var row=rows.getFirst();String kind=row.get("kind").toString();if(db.queryForObject("SELECT count(*) FROM "+accounts+" WHERE id=? AND "+active(),Integer.class,uid)==0){suppress(id,"ACCOUNT_UNAVAILABLE");return;}if(!allowed(uid,kind)){suppress(id,"PREFERENCE_DISABLED");return;}if(((java.sql.Timestamp)row.get("created_at")).toInstant().isBefore(Instant.now().minus(Duration.ofDays(30)))){suppress(id,"EXPIRED");return;}
  if(!authorized(row,uid)){suppress(id,"RESOURCE_UNAVAILABLE");return;}
  if(kind.equals("NEW_MATCH")&&deferDigest(row,uid,id))return;
  var s=settings(uid);long today=db.queryForObject("SELECT count(*) FROM communication_deliveries WHERE user_id=? AND status='DELIVERED' AND delivered_at>=date_trunc('day',CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'",Long.class,uid);
  if(today>=num(s,"daily_limit")){Instant next=LocalDate.now(ZoneId.of("America/Sao_Paulo")).plusDays(1).atStartOfDay(ZoneId.of("America/Sao_Paulo")).toInstant();db.update("UPDATE communication_deliveries SET next_attempt_at=?,reason='DAILY_LIMIT' WHERE id=?",java.sql.Timestamp.from(next),id);return;}
  var last=db.queryForList("SELECT delivered_at FROM communication_deliveries WHERE user_id=? AND kind=? AND status='DELIVERED' ORDER BY delivered_at DESC LIMIT 1",uid,kind);if(!last.isEmpty()){Instant next=((java.sql.Timestamp)last.getFirst().get("delivered_at")).toInstant().plusSeconds(num(s,"minimum_interval_minutes")*60);if(next.isAfter(Instant.now())){db.update("UPDATE communication_deliveries SET next_attempt_at=?,reason='FREQUENCY_LIMIT' WHERE id=?",java.sql.Timestamp.from(next),id);return;}}
  Object legacy=null;if(row.get("legacy_kind")!=null){var inserted=db.queryForList("INSERT INTO learning_notifications(user_id,question_id,message_id,kind) VALUES (?,?,?,?) ON CONFLICT DO NOTHING RETURNING id",uid,num(row,"resource_id"),row.get("legacy_message_id"),row.get("legacy_kind"));if(inserted.isEmpty()){var existing=db.queryForList("SELECT id FROM learning_notifications WHERE user_id=? AND question_id=? AND message_id IS NOT DISTINCT FROM ? AND kind=? ORDER BY id DESC LIMIT 1",uid,num(row,"resource_id"),row.get("legacy_message_id"),row.get("legacy_kind"));if(!existing.isEmpty())legacy=existing.getFirst().get("id");}else legacy=inserted.getFirst().get("id");}
  var template=CommunicationTemplates.render(trail,kind);db.update("UPDATE communication_deliveries SET status='DELIVERED',reason=NULL,attempts=attempts+1,title=?,body=?,target=?,template_version=?,legacy_id=?,delivered_at=CURRENT_TIMESTAMP WHERE id=?",template.title(),template.body(),template.target(),template.version(),legacy,id);
 }
 private boolean deferDigest(Map<String,Object> row,long uid,long id){
  try{String raw=db.queryForObject("SELECT alert_preferences FROM app_users WHERE id=?",String.class,uid);String frequency=json.readTree(raw).path("frequency").asText("weekly");if(frequency.equals("immediate"))return false;
   var events=db.queryForList("SELECT created_at FROM communication_events WHERE source_key=?",row.get("event_key"));Object timestamp=events.isEmpty()?row.get("created_at"):events.getFirst().get("created_at");Instant ready=CommunicationSchedule.digestAfter(((java.sql.Timestamp)timestamp).toInstant(),frequency);
   if(ready.isAfter(Instant.now())){db.update("UPDATE communication_deliveries SET next_attempt_at=?,reason='DIGEST_SCHEDULED' WHERE id=?",java.sql.Timestamp.from(ready),id);return true;}return false;
  }catch(com.fasterxml.jackson.core.JsonProcessingException invalid){suppress(id,"PREFERENCE_INVALID");return true;}
 }
 private boolean authorized(Map<String,Object> row,long uid){long resource=num(row,"resource_id"),scope=num(row,"scope_id");String kind=row.get("kind").toString();if(trail.equals("OPORTUNIDADES"))return kind.equals("NEW_MATCH")?matches(uid,resource):kind.equals("APPLICATION_UPDATED")&&db.queryForObject("SELECT count(*) FROM job_applications WHERE id=? AND user_id=?",Integer.class,resource,uid)>0;
  if(trail.equals("EMPRESAS")&&kind.equals("TRUST_REVIEW"))return db.queryForObject("SELECT count(*) FROM companies c JOIN company_users u ON u.id=? AND u.email_verified=TRUE AND u.account_status='ACTIVE' WHERE c.id=? AND (c.owner_user_id=u.id OR EXISTS(SELECT 1 FROM company_members m WHERE m.company_id=c.id AND m.user_id=u.id AND m.role IN ('OWNER','ADMIN','RECRUITER')))",Integer.class,uid,scope)>0;
  if(trail.equals("EMPRESAS"))return db.queryForObject("SELECT count(*) FROM company_applications a JOIN company_listings l ON l.id=a.listing_id JOIN companies c ON c.id=l.company_id WHERE a.id=? AND c.id=? AND c.verification_status<>'SUSPENDED' AND (c.owner_user_id=? OR EXISTS(SELECT 1 FROM company_members m WHERE m.company_id=c.id AND m.user_id=? AND m.role IN ('OWNER','RECRUITER')))",Integer.class,resource,scope,uid,uid)>0;
  if(row.get("legacy_kind")!=null)return !db.queryForList("SELECT q.id FROM learning_questions q JOIN learning_courses c ON c.id=q.course_id WHERE q.id=? AND (q.student_id=? OR c.teacher_id=?) FOR KEY SHARE OF q NOWAIT",resource,uid,uid).isEmpty();
  if(db.queryForObject("SELECT count(*) FROM learning_lesson_progress p JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id WHERE p.student_id=? AND s.course_id=?",Integer.class,uid,scope)==0)return false;
  if(kind.equals("COURSE_CHANGED"))return db.queryForObject("SELECT count(*) FROM learning_courses WHERE id=?",Integer.class,scope)>0;
  if(kind.equals("ASSESSMENT_AVAILABLE"))return db.queryForObject("SELECT count(*) FROM learning_assessments a JOIN learning_courses c ON c.id=a.course_id JOIN student_users t ON t.id=c.teacher_id WHERE a.id=? AND a.course_id=? AND a.status='PUBLISHED' AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND t.account_status='ACTIVE' AND a.current_version_id=?",Integer.class,resource,scope,Long.parseLong(row.get("event_key").toString().substring("assessment-version:".length())))>0;return false;
 }
 public void retain(){db.update("DELETE FROM communication_deliveries WHERE id IN (SELECT id FROM communication_deliveries WHERE created_at<CURRENT_TIMESTAMP-INTERVAL '90 days' ORDER BY id LIMIT 500)");db.update("DELETE FROM communication_events WHERE id IN (SELECT id FROM communication_events WHERE state<>'PENDING' AND created_at<CURRENT_TIMESTAMP-INTERVAL '90 days' ORDER BY id LIMIT 500)");db.update("DELETE FROM communication_preference_audit WHERE id IN (SELECT id FROM communication_preference_audit WHERE created_at<CURRENT_TIMESTAMP-INTERVAL '90 days' ORDER BY id LIMIT 500)");}
 private static long num(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 private static void bad(){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Revise as categorias, revisão e limites das preferências.");}
}
